function inspectCellReadiness(){
 if(processPreviewMode){const rows=(flowState.stationInstanceIds||[]).map(id=>doc.instances.find(i=>i.id===id)).filter(Boolean).map(i=>({instanceId:i.id,assetId:i.assetId,label:i.label||i.assetId,reasons:['작업물 경로용 Anchor 후보 · 높이/공정/설비 동작 미검증'],ready:!!PROCESS_ANCHORS[i.assetId],stateOnly:true}));return {rows,ready:rows.length>=2&&rows.every(x=>x.ready),mode:'FUNCTIONAL_DEMO_WORKPIECE_PATH'};}
 const edges=(doc?.relationships||[]).filter(e=>['RELATED_CELL_SELECTION','PROCESS_CELL_PRESET'].includes(e.source?.method));
 const ids=new Set(edges.flatMap(e=>[e.from,e.to]));
 const rows=(doc?.instances||[]).filter(i=>ids.has(i.id)&&i.assetId).map(i=>{
  const asset=window.P006_FUNCTIONAL_SIM?.registry?.assets?.find(a=>a.assetId===i.assetId);
  const contracts=(asset?.motion?.contracts||[]).filter(c=>c.motionType&&c.targetNode);
  const object=threeState.group?.children?.find(o=>o.userData?.instanceId===i.id);
  const resolved=contracts.length>0&&contracts.every(c=>object?.getObjectByName(c.targetNode));
  const reasons=[];
  if(!PROCESS_ANCHORS[i.assetId])reasons.push('입출력 위치·거치 높이 미등록');
  if(!contracts.length)reasons.push('기계 동작 없음: 상태 표시만 등록됨');
  else if(!resolved)reasons.push('3D 가동부 로딩·확인 필요');
  if(contracts.some(c=>!c.axis&&!c.localAxis))reasons.push('동작 축·Pivot 근거 확인 필요');
  return {instanceId:i.id,assetId:i.assetId,label:i.label||i.assetId,reasons,ready:!reasons.includes('입출력 위치·거치 높이 미등록'),stateOnly:!contracts.length};
 });
 return {rows,ready:rows.length>0&&rows.every(r=>r.ready)};
}
function showCellReadiness(){
 const result=inspectCellReadiness();let panel=document.getElementById('cellReadinessDialog');
 if(!panel){panel=document.createElement('dialog');panel.id='cellReadinessDialog';document.body.append(panel);}
 panel.replaceChildren();const title=document.createElement('h3');title.textContent='공정 재생 준비 상태';panel.append(title);
 const close=document.createElement('button');close.textContent='닫기';close.onclick=()=>panel.close();panel.append(close);
 for(const r of result.rows){const p=document.createElement('p');p.textContent=r.label+' ('+r.assetId+') — '+(r.ready?'기본 연결 확인':r.reasons.join(' / '));panel.append(p);}
 if(!result.rows.length){const p=document.createElement('p');p.textContent='구성된 공정 셀이 없습니다.';panel.append(p);}
 const note=document.createElement('p');note.textContent='순차 실행에는 작업물 경로와 도착 후 동작·완료 조건이 필요합니다. 현재 화면은 해당 조건의 준비 여부를 검사합니다.';panel.append(note);
 if(!panel.open)panel.showModal();return result;
}
