  const workpiece={id:uuid(),assetId:null,entryUsd:null,templateId:'workpiece',equipmentId:null,intakeId:null,label:'작업물 · 공정 대상',position:[-7,.35,0],rotation:[0,0,0],scale:[1,1,1],parameters:{width:.7,length:1,height:.5}};
