function processCellBounds(){const xs=[],zs=[];for(const i of (doc?.instances||[]).filter(i=>!['wall','aisle','door','zone','floor','building'].includes(i.templateId)&&i.position)){const d=dims(i),sx=Math.abs(i.scale?.[0]||1),sz=Math.abs(i.scale?.[2]||1);xs.push(i.position[0]-d[0]*sx/2,i.position[0]+d[0]*sx/2);zs.push(i.position[2]-d[2]*sz/2,i.position[2]+d[2]*sz/2);}if(!xs.length)return null;return {minX:Math.min(...xs),maxX:Math.max(...xs),minZ:Math.min(...zs),maxZ:Math.max(...zs)};}
