    list(s.intermediateConnectionAssets).forEach(r=>add(r,'중간 연결 설비 필요','master.intermediateConnectionAssets'));
    const rel=assetContractRegistry.get(id)?.relatedAssets||catalog.relatedAssets||catalog.related_assets||{};
    list(rel.connectionProducts||rel.direct).forEach(r=>add(r,'직접 연결','registry.relatedAssets'));
    list(rel.intermediate).forEach(r=>add(r,'중간 연결 설비 필요','registry.relatedAssets'));
